  const casts = (s, cardId) => legalActionsForPlayer(s, "user").filter((a) => a.kind === "cast-spell" && a.cardId === cardId);
  const cost = (s, cardId) => { const c = casts(s, cardId)[0]?.cost; return c ? ["generic", "W", "U", "B", "R", "G"].map((k) => c[k] || 0).join(",") : null; };
  const handBear = { hand: [K("bear", BEARS)], pool: { G: 2 } };
