    const under = s([MW()]);
    const act = casts(under, "bear")[0];
    const after = act ? dispatchAction(under, act) : null;
    expect({ plain: casts(s([]), "bear").length, under: !!act, onStack: (after?.stack || []).some((o) => o.source?.name === "Grizzly Bears") })
      .toEqual({ plain: 0, under: true, onStack: true });
